const enfermedadData=[{"disease":"«Más de mil descargas» y nadie pregunta de cuántos ni cuándo","characteristic":"Cifra sin denominador ni fecha","opts":["Cifra sin denominador ni fecha","Futuro contado en presente","Adjetivo que tapa el dato","Nosotros que agranda"]},{"disease":"«Trabajamos con escuelas» cuando hay una y de prueba","characteristic":"Futuro contado en presente","opts":["Futuro contado en presente","Cifra sin denominador","Falta de prueba","Relato caducado"]},{"disease":"«Una plataforma innovadora y líder en su categoría»","characteristic":"Adjetivos que ocupan el sitio de las cifras","opts":["Adjetivos que ocupan el sitio de las cifras","Cifra sin denominador","Nosotros que agranda","Falta de fuente"]},{"disease":"«Nuestro equipo de contenidos» cuando son cuatro de una casa","characteristic":"El nosotros que agranda el tamaño real","opts":["El nosotros que agranda el tamaño real","Futuro en presente","Adjetivo que tapa el dato","Cifra sin fecha"]},{"disease":"El texto de presentación describe un proyecto que ya no existe","characteristic":"El relato se quedó viejo y nadie le puso fecha","opts":["El relato se quedó viejo y nadie le puso fecha","Faltaban adjetivos","La audiencia era la equivocada","El canal no era el correcto"]},{"disease":"Se afirmó que la ficha tenía diez páginas y el PDF tenía diecinueve","characteristic":"Se afirmó sin comprobar contra la fuente","opts":["Se afirmó sin comprobar contra la fuente","La ficha estaba mal hecha","El formato era el equivocado","Faltaba revisar la ortografía"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

