const identifyTaskDB=[{"s":"La versión corta y verdadera que otro repite.","type":"El relato"},{"s":"Una afirmación que otro puede verificar sin creerte.","type":"Hecho comprobable"},{"s":"De cuántos y en cuánto tiempo.","type":"El denominador"},{"s":"Decir en presente algo que todavía no ocurrió.","type":"Futuro contado en presente"},{"s":"La palabra que ocupa el sitio de una cifra.","type":"Adjetivo que tapa el dato"},{"s":"Lo que se pone sobre la mesa y no se discute.","type":"La prueba que se toca"},{"s":"La parte que dices tú antes de que la descubran.","type":"Lo que todavía no es"},{"s":"De dónde sale cada afirmación.","type":"La fuente"},{"s":"Lo que hace que un relato viejo mienta sin querer.","type":"La falta de fecha"},{"s":"Las cinco piezas en una sola hoja.","type":"El relato de una página"}];
