const completeTaskDB=[{"s":"La versión corta y verdadera que otro repite es el ___.","opts":["relato","anuncio","resumen"],"ans":"relato"},{"s":"Una cifra sin ___ engaña sin mentir.","opts":["denominador","titular","color"],"ans":"denominador"},{"s":"Los adjetivos ocupan el sitio de los ___.","opts":["datos","logos","precios"],"ans":"datos"},{"s":"Lo que se pone sobre la mesa es la ___.","opts":["prueba","promesa","oferta"],"ans":"prueba"},{"s":"Decir lo que falta hace ___ el resto.","opts":["creíble","corto","barato"],"ans":"creíble"},{"s":"Un relato sin ___ envejece y miente solo.","opts":["fecha","logo","firma"],"ans":"fecha"},{"s":"De dónde sale una afirmación es su ___.","opts":["fuente","formato","función"],"ans":"fuente"},{"s":"Inflar es un préstamo contra la ___.","opts":["confianza","audiencia","promesa"],"ans":"confianza"}];
const explainQuestions=[{"q":"Explica qué es el relato de un proyecto y en qué se diferencia de la publicidad.","ans":"El relato es la versión corta y verdadera de qué es esto, para quién, qué ha pasado ya y qué falta: lo que otra persona repite cuando tú no estás delante. La publicidad la controlas tú y se paga; el relato lo repite otro y por eso no puede llevar nada que no aguante una comprobación. La diferencia práctica es qué pasa cuando alguien abre el producto: si el relato era cierto, lo que encuentra confirma lo que le contaron y la confianza sube; si estaba inflado, lo que encuentra lo desmiente, y entonces no discute contigo, simplemente no vuelve. Por eso el relato se escribe con hechos comprobables y cifras con denominador, no con adjetivos."},{"q":"¿Qué es una cifra con denominador y por qué una cifra pequeña convence más que una grande?","ans":"Una cifra con denominador dice de cuántos y en cuánto tiempo: no «cuarenta», sino «cuarenta de una sección de cuarenta y dos, en marzo». Sin eso, el número no significa nada y además es la forma más educada de exagerar, porque no llega a ser mentira y engaña igual. Una cifra pequeña y exacta convence más que una grande y borrosa porque se puede comprobar en el momento y porque enseña que quien la dice sabe contar lo suyo. «Veintidós estudiantes de sexto, en marzo» abre una conversación que «cientos de usuarios» cierra, porque lo segundo obliga a la otra persona a decidir si te cree, y casi nadie quiere quedar en esa posición."},{"q":"Nombra las cuatro formas de inflar un relato y da un ejemplo de cada una.","ans":"Primera, la cifra sin denominador ni fecha: «más de mil descargas», sin decir de cuántos ni cuándo. Segunda, el futuro contado en presente: «trabajamos con escuelas» cuando hay una y de prueba; es la más común y la más fácil de justificarse por dentro, porque uno cree de verdad que va a pasar. Tercera, el adjetivo que tapa el dato: «innovador», «líder», «revolucionario», cada uno ocupando el sitio de una cifra que no se quiso decir. Cuarta, el nosotros que agranda: «nuestro equipo de contenidos» cuando son cuatro personas de una casa, que además obliga después a sostener un tamaño que no se tiene. Las cuatro se corrigen igual: quitar y sustituir por lo que sí se puede comprobar."},{"q":"¿Por qué decir lo que el proyecto todavía no es hace más creíble el resto del relato?","ans":"Porque quien escucha está calculando, sin decirlo, cuánto hay que descontar de lo que le cuentan. Si el relato nombra sus propios límites, ese descuento desaparece: ya no hace falta buscar lo que se está callando, porque se dijo primero. Además cambia quién controla el momento: los límites de un proyecto se descubren siempre, y no es lo mismo que los diga uno con calma a que los encuentre la otra persona sola y en mal momento. En M.E.T.A.S eso significa decir que la ruta tiene seis etapas y hay tres construidas, que la escuela es una y de prueba, y que falta probar el material con maestros de fuera de la casa. Ninguna de las tres cosas resta: todas hacen que el resto se pueda creer."},{"q":"Explica por qué un relato lleva fecha, con el caso del texto de presentación de este proyecto.","ans":"Un relato escrito hace un año miente sin querer, no porque haya cambiado la verdad sino porque ha cambiado el proyecto. El README de este repositorio es el ejemplo de la casa: sigue presentando una colección de actividades de gramática y enlazando el sitio público, cuando lo que hay hoy es una aplicación privada de la familia con diecisiete misiones, nueve rutas, la Bóveda, el chat y las finanzas. Nadie mintió: el texto se quedó quieto mientras lo demás se movía. Por eso el relato lleva fecha y fecha de revisión, igual que un dato lleva plazo de borrado, y por eso revisarlo es una tarea con día en el calendario y no algo que se hace «cuando haga falta», que nunca llega."},{"q":"Un patrocinador ofrece 8.000 lempiras y pide que se le llame «alianza estratégica». ¿Qué se contesta y con qué condición?","ans":"Mete dinero que sirve, y en un proyecto de casa 8.000 lempiras cubren impresión y hospedaje un buen tiempo. Saca algo que no se ve en el momento: la palabra «alianza» describe una relación que no existe, y quien la lea va a suponer un compromiso mutuo, una continuidad y un respaldo que nadie ha firmado. El día que alguien pregunte en qué consiste la alianza, no hay respuesta, y el que queda mal no es el patrocinador. La condición con la que sí: se acepta el dinero y se le llama por su nombre, «patrocinio de la edición de marzo», con el logotipo en el sitio acordado y la fecha. Si el patrocinador necesita la palabra alianza para que le sirva, entonces lo que quiere no es patrocinar: es figurar, y eso se negocia aparte."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

