const evalTFBank=[{"q":"El relato es lo que otra persona repite cuando tú no estás delante.","a":true},{"q":"Una cifra sin denominador ni fecha ya dice algo útil.","a":false},{"q":"«Trabajamos con escuelas» con una escuela de prueba es futuro contado en presente.","a":true},{"q":"Los adjetivos como «innovador» suplen bien la falta de cifras.","a":false},{"q":"Una cifra pequeña y exacta convence más que una grande y borrosa.","a":true},{"q":"Decir lo que el proyecto todavía no es le quita fuerza al relato.","a":false},{"q":"El relato cambia el énfasis según el público, pero no cambia los datos.","a":true},{"q":"Un relato sin fecha puede volverse falso sin que nadie lo toque.","a":true},{"q":"Llamar «nuestro equipo» a cuatro personas de una casa no tiene consecuencias.","a":false},{"q":"La prueba que se puede tocar vale más que la frase que la describe.","a":true},{"q":"Inflar el relato se cobra el día que alguien abre el producto.","a":true},{"q":"Quien afirma algo es quien tiene que enseñar la fuente.","a":true},{"q":"Si nadie desmiente una exageración en la reunión, es que no hubo daño.","a":false},{"q":"El relato de una página tiene cinco piezas: qué es, para quién, qué pasó, qué falta y qué se pide.","a":true},{"q":"La misma verdad se puede contar en una frase, en un minuto y en una página.","a":true}];
const evalMCBank=[{"q":"El relato de un proyecto es…","o":["a) La versión corta y verdadera que otro repite","b) El eslogan y la identidad visual","c) La lista completa de logros","d) La presentación para pedir dinero"],"a":0},{"q":"«Más de mil descargas» falla porque…","o":["a) No lleva denominador ni fecha","b) Es un número muy pequeño","c) No menciona la audiencia","d) Se dice en presente"],"a":0},{"q":"El futuro contado en presente es…","o":["a) Prometer una función que se va a construir","b) Hablar de planes a cinco años","c) Decir «trabajamos con escuelas» con una y de prueba","d) Usar verbos en futuro"],"a":2},{"q":"Ante un adjetivo como «líder», lo que se hace es…","o":["a) Acompañarlo de un logotipo","b) Repetirlo para que se fije","c) Reservarlo para quien pone dinero","d) Quitarlo y ver qué cifra queda en pie"],"a":3},{"q":"El «nosotros que agranda» es un problema porque…","o":["a) Suena poco profesional","b) Obliga a sostener un tamaño que no se tiene","c) Confunde a la audiencia sobre el precio","d) Es más largo de escribir"],"a":1},{"q":"La prueba que se toca es…","o":["a) Una frase bien escrita sobre la calidad","b) El testimonio de un conocido","c) El número de seguidores","d) La ficha impresa o la aplicación abierta en el teléfono"],"a":3},{"q":"Decir lo que el proyecto todavía no es sirve para…","o":["a) Bajar las expectativas de precio","b) Cumplir un requisito formal","c) Ganar tiempo antes de decidir","d) Que el resto del relato se pueda creer"],"a":3},{"q":"Cuando el relato se cuenta a tres públicos distintos, cambia…","o":["a) Los datos, según lo que cada uno espera","b) El nombre del proyecto","c) El énfasis y el largo, nunca los datos","d) Nada en absoluto"],"a":2},{"q":"Un relato lleva fecha porque…","o":["a) Lo exige el formato","b) El proyecto cambia y el texto no","c) Sirve para cobrar","d) Ayuda a la memoria del autor"],"a":1},{"q":"La consecuencia real de inflar es…","o":["a) Que alguien te desmienta en la reunión","b) Que la competencia lo copie","c) Que quien abra el producto no vuelva","d) Que suba el precio esperado"],"a":2},{"q":"Ante «¿cuántas escuelas lo usan?», la mejor respuesta es…","o":["a) «Varias, y creciendo»","b) «Una, en prueba desde enero, y buscamos la segunda»","c) «No damos ese dato»","d) «Las suficientes para sostenernos»"],"a":1},{"q":"La fuente de una afirmación…","o":["a) La enseña quien afirma","b) La pide quien duda","c) Solo hace falta en textos técnicos","d) Se puede omitir si hay confianza"],"a":0},{"q":"El relato de una página se compone de…","o":["a) Portada, índice y anexos","b) Historia, misión, visión y valores","c) Qué es, para quién, qué pasó, qué falta y qué se pide","d) Problema, solución y precio"],"a":2},{"q":"Un patrocinio de una edición que se anuncia como «alianza estratégica»…","o":["a) Describe una relación que no existe","b) Es la forma habitual de nombrarlo","c) Beneficia por igual a los dos","d) Solo importa si hay contrato"],"a":0},{"q":"La prueba de que esta etapa está aprendida es…","o":["a) Tener un eslogan memorable","b) Poder decir el proyecto en una frase, un minuto y una página, sin cambiar un dato","c) Haber publicado en varios canales","d) Saberse las cifras de memoria"],"a":1}];
