function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"El texto de presentación del repositorio sigue describiendo una colección de actividades de gramática y enlaza el sitio público, cuando hoy F.A.R.O es la aplicación privada de la familia con diecisiete misiones y nueve rutas."},{"txt":"Las tarjetas de las misiones familiares pintan un candado y dicen «material de la casa», mientras el repositorio se lee entero desde internet."},{"txt":"Se afirmó que la ficha tenía diez páginas. Al llevarla a PDF tenía diecinueve, y nadie lo había comprobado antes de decirlo."},{"txt":"En una reunión preguntan cuántas escuelas usan las misiones. Hay una, en prueba, desde enero, y la tentación es contestar «varias»."},{"txt":"Un patrocinador local ofrece 8.000 lempiras para imprimir fichas y pide que en la portada y en el sitio se le nombre «alianza estratégica»."},{"txt":"El resumen semanal de la Antena trae el mejor día del mes muy por encima del resto, y se plantea enseñar ese dato solo, sin el promedio."},{"txt":"La revista PolicastSapien va a publicar un reportaje investigativo con una cifra que llegó por un mensaje reenviado, sin fuente que la respalde."},{"txt":"Una maestra pregunta si el material está probado en el aula. Se usó en una sección de sexto y nunca lo ha revisado un maestro de fuera de la casa."}];
const critCaseQuestions=["1. ¿Qué se está afirmando exactamente, y qué parte de eso se puede comprobar hoy?","2. ¿Cuál de las cuatro formas de inflar aparece aquí, y cómo se corrige?","3. Escribe en 3-4 frases lo que dirías tú, con cifra, denominador y fecha.","4. ¿Qué se pierde el día que alguien abra el producto y no sea lo que se contó?"];
const critCaseGuides=["Separar la afirmación de lo comprobable: casi siempre hay un hecho verdadero pequeño debajo de la frase grande. Ese hecho es el que se dice.","Cifra sin denominador, futuro contado en presente, adjetivo que tapa el dato o nosotros que agranda. Se corrigen quitando y sustituyendo por lo que sí se puede enseñar.","La respuesta buena casi nunca es más larga: es más concreta. Y suele incluir lo que todavía no es, porque eso es lo que hace creíble lo demás.","Nunca se pierde en el momento. Se pierde después, y no en forma de discusión: en forma de una persona que ya no vuelve y que además lo cuenta."];

const critErrorBank=[{"txt":"\"Pon que trabajamos con escuelas, total en unos meses va a ser cierto\".","g1":"Es el futuro contado en presente, la forma más común de inflar y la más fácil de justificarse por dentro. Quien lo lea va a decidir cosas hoy con un dato que todavía no existe.","g2":"Se dice lo que hay con su fecha: una escuela, en prueba, desde enero. Y se añade lo que se busca, que además convierte el relato en una petición concreta."},{"txt":"\"Mil descargas suena bien, no hace falta decir de cuánto tiempo\".","g1":"Una cifra sin denominador ni fecha no es mentira y engaña igual, que es justo lo que la hace peligrosa: no se puede defender ni se puede desmentir.","g2":"Se pone el denominador y el plazo, aunque el número quede más pequeño. Una cifra chica y exacta abre conversaciones que una grande y borrosa cierra."},{"txt":"\"Le ponemos innovador y de calidad, que queda mejor que la lista de lo que hace\".","g1":"Cada adjetivo así ocupa el sitio de una cifra que no se quiso decir, y quien escucha lo sabe: por eso los descuenta automáticamente.","g2":"Se tachan todos los adjetivos y se mira qué queda en pie. Lo que quede es el relato; lo demás era relleno."},{"txt":"\"Mejor decir nuestro equipo, así no parece cosa de una familia\".","g1":"El nosotros que agranda obliga a sostener después un tamaño que no se tiene, y la primera pregunta concreta lo derrumba.","g2":"Cuatro personas de una casa no es una debilidad del relato: es lo que explica el precio, la cercanía y por qué las fichas se prueban en la mesa del comedor."},{"txt":"\"El texto de presentación lleva un año igual, pero nadie se queja\".","g1":"Un relato viejo miente sin que nadie lo toque. Que nadie se queje no significa que nadie se lo esté creyendo.","g2":"Se lee entero como si fuera de otro, se marca lo que ya no es cierto, se corrige con la fecha de hoy y se apunta la fecha de la próxima revisión."},{"txt":"\"Enseñamos el mejor día del mes, que es un dato real\".","g1":"Es real y es una exageración: elegir el mejor punto y presentarlo como lo normal es inflar sin escribir una sola cifra falsa.","g2":"Se enseña el promedio y, si el pico interesa, se dice que fue un pico y qué lo causó. Eso además es más útil, porque explica algo."}];

const critDecisionBank=["El texto de presentación del proyecto quedó viejo: ¿qué se corrige primero y qué se le pone para que no vuelva a pasar?","El candado dice «material de la casa» y el repositorio se lee desde internet: ¿qué se cambia, el candado o el repositorio?","Se afirmó que la ficha tenía diez páginas y tenía diecinueve: ¿qué regla nace de ahí y cómo se comprueba de ahora en adelante?","Preguntan cuántas escuelas usan las misiones y hay una, en prueba: ¿qué contestas, con qué cifra y con qué fecha?","Un patrocinador de 8.000 lempiras quiere que se le llame «alianza estratégica»: ¿qué se acepta y con qué condición?","El resumen semanal trae un pico muy por encima del promedio: ¿qué dato se enseña y cómo se explica?","La revista va a publicar una cifra que llegó por un mensaje reenviado: ¿se publica, se busca fuente o se quita?","Una maestra pregunta si el material está probado en el aula: ¿qué se dice de lo que hay y de lo que falta?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se separa el hecho comprobable de la frase grande que lo envuelve, porque debajo de casi toda exageración hay una verdad pequeña que sirve; después se le pone denominador y fecha a cada cifra, aunque el número quede menor; después se nombra lo que todavía no es, que es lo que hace creíble el resto; y al final se decide qué prueba se pone sobre la mesa, porque una ficha impresa o la aplicación abierta valen más que cualquier frase. Si la respuesta no se puede comprobar delante de quien pregunta, todavía no es el relato: es publicidad.';

const critCompareBank=[{"a":"«Una escuela, en prueba desde enero, y buscamos la segunda».","b":"«Trabajamos con escuelas del país».","ga":"Caso A: se puede comprobar, se puede nombrar, y encima convierte el relato en una petición concreta.","gb":"Caso B: quien lo lea decide hoy con un dato que no existe, y la primera pregunta concreta lo derrumba."},{"a":"«Veintidós de sexto completaron la misión en marzo».","b":"«Cientos de estudiantes usan nuestras misiones».","ga":"Caso A: cifra pequeña con denominador y fecha, verificable en el momento, y enseña que quien la dice sabe contar lo suyo.","gb":"Caso B: obliga a la otra persona a decidir si te cree, y casi nadie quiere quedar en esa posición."},{"a":"Poner la ficha impresa y el teléfono con la aplicación sobre la mesa.","b":"Explicar con detalle lo buena que es la ficha.","ga":"Caso A: la prueba se toca y no admite discusión; además deja a la otra persona sacando sus propias conclusiones.","gb":"Caso B: cuanto mejor se describe, más descuenta quien escucha, porque describir bien no cuesta nada."},{"a":"Llamarlo «patrocinio de la edición de marzo», con su fecha.","b":"Llamarlo «alianza estratégica».","ga":"Caso A: describe lo que de verdad pasó, y el patrocinador queda igual de visible sin que nadie tenga que sostener nada.","gb":"Caso B: describe una relación que no existe, y el día que alguien pregunte en qué consiste, el que queda mal no es el patrocinador."}];

const critCauseBank=[{"cause":"Se cuenta en presente algo que todavía no ocurrió.","guide":"Quien escucha toma decisiones hoy con un dato que no existe, y la primera pregunta concreta derrumba el resto del relato con él."},{"cause":"Se da una cifra sin denominador ni fecha.","guide":"El número no se puede defender ni desmentir, así que no convence a quien sabe y desactiva a quien no. No es mentira y engaña igual."},{"cause":"Se llenan los huecos con adjetivos.","guide":"Cada adjetivo ocupa el sitio de una cifra que no se quiso decir, y quien escucha los descuenta automáticamente: el relato queda más débil que si no se hubiera dicho nada."},{"cause":"El relato no lleva fecha ni se revisa.","guide":"Se vuelve falso sin que nadie lo toque, porque el proyecto se mueve y el texto no. Y como nadie se queja, nadie se entera."},{"cause":"Se enseña el mejor dato y se calla el promedio.","guide":"Es exagerar sin escribir una sola cifra falsa, y es lo más difícil de defender después, porque la otra persona ya no sabe qué más se eligió a dedo."},{"cause":"Se afirma algo sin comprobarlo contra la fuente.","guide":"Basta una vez para que todo lo demás pase a revisión. Y la fuente casi siempre estaba a un minuto de distancia."}];
const critEffectBank=[{"effect":"La maestra volvió a la semana siguiente y trajo a otra.","guide":"Lo que encontró al abrir el material confirmaba lo que le habían contado. Ese es todo el mecanismo de la confianza."},{"effect":"Una cifra pequeña abrió una reunión que una grande habría cerrado.","guide":"Se pudo comprobar en el momento, y quien la escuchó no tuvo que decidir si creía o no: pudo verlo."},{"effect":"Nadie preguntó dos veces por el tamaño del proyecto.","guide":"Se dijo desde el principio que lo hacen cuatro personas de una casa, así que no quedó nada que descubrir."},{"effect":"El texto de presentación siguió siendo cierto un año después.","guide":"Llevaba fecha y fecha de revisión, y esa revisión se hizo el día que tocaba, no cuando hizo falta."},{"effect":"El patrocinador quedó visible y nadie tuvo que explicar nada.","guide":"Se le llamó por su nombre, patrocinio de una edición concreta, y con eso no hubo relación que sostener después."},{"effect":"Una afirmación dudosa no llegó a publicarse en la revista.","guide":"Se pidió la fuente antes de imprimir, y como no apareció, se quitó. Costó un párrafo y salvó el reportaje entero."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El relato que se sostiene · Forma ${cf} · El relato · Ruta de la Marca`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué se está afirmando, qué parte de eso se puede comprobar hoy y cómo lo dirías tú con cifra, denominador y fecha? Explica por qué tu versión convence más que la inflada.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos aguanta que alguien lo comprobe delante de ti? 2. ¿Por qué no dicen lo mismo?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El relato que se sostiene: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué se está afirmando, qué parte de eso se puede comprobar hoy y cómo lo dirías tú con cifra, denominador y fecha? Explica por qué tu versión convence más que la inflada.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos aguanta que alguien lo comprobe delante de ti? 2. ¿Por qué no dicen lo mismo?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El relato que se sostiene · El relato · Ruta de la Marca · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El relato que se sostiene · El relato · Ruta de la Marca · Etapa 3 · Marketing y Marca</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El relato que se sostiene · El relato · Ruta de la Marca · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

