const timelineData=[{"y":"1","icon":"📣","label":"Qué es esto","text":"Una <strong>frase sin adjetivos</strong> que diga qué es. <strong>Decide:</strong> si la otra persona sigue escuchando. <strong>Se rompe:</strong> con «plataforma innovadora». <strong>En M.E.T.A.S:</strong> misiones interactivas y fichas imprimibles para primaria."},{"y":"2","icon":"🎯","label":"Para quién","text":"La <strong>audiencia concreta</strong> de la etapa 1, con el nombre de quien lo usa. <strong>Decide:</strong> qué se cuenta después. <strong>Se rompe:</strong> con «para todo el mundo». <strong>En M.E.T.A.S:</strong> la maestra de primaria y la madre que solo tiene el teléfono."},{"y":"3","icon":"📊","label":"Qué ya pasó","text":"Las <strong>cifras con denominador y fecha</strong>. <strong>Decide:</strong> si te creen. <strong>Se rompe:</strong> con «cientos» y «más de mil». <strong>En M.E.T.A.S:</strong> diecisiete misiones, nueve rutas, una escuela en prueba desde enero."},{"y":"4","icon":"🧾","label":"Con qué se prueba","text":"La <strong>evidencia que se toca</strong>: un archivo, una fecha, una ficha impresa. <strong>Decide:</strong> si hace falta creerte. <strong>Se rompe:</strong> al describir en vez de enseñar. <strong>En M.E.T.A.S:</strong> la ficha en la mano y la aplicación abierta en el teléfono."},{"y":"5","icon":"🚧","label":"Qué todavía no es","text":"El <strong>límite dicho por uno mismo</strong>, antes de que lo descubran. <strong>Decide:</strong> cuánto descuenta quien escucha. <strong>Se rompe:</strong> al esperar a que pregunten. <strong>En M.E.T.A.S:</strong> falta probarlo con maestros de fuera de la casa."},{"y":"6","icon":"🙋","label":"Qué se pide","text":"La <strong>petición concreta</strong>, en una línea. <strong>Decide:</strong> qué pasa después de la reunión. <strong>Se rompe:</strong> con «cualquier apoyo es bienvenido». <strong>En M.E.T.A.S:</strong> una segunda escuela que quiera probar un mes."},{"y":"7","icon":"📅","label":"Cuándo caduca","text":"La <strong>fecha del relato y la de su revisión</strong>. <strong>Decide:</strong> que no mienta solo. <strong>Se rompe:</strong> al no ponerla nunca. <strong>En M.E.T.A.S:</strong> el texto de presentación del repositorio, que se quedó en el proyecto anterior."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

