let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(loDices){sfx(loDices?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(loDices){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📊</span><span class="ms-text"><strong>Dijiste el número con su contexto:</strong> «una, en prueba desde enero, y estamos buscando la segunda». Nadie se decepcionó, porque nadie se había hecho una idea que no era.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🙋</span><span class="ms-text"><strong>Y la respuesta se convirtió en una petición:</strong> al decir que buscas la segunda, la pregunta deja de ser un examen y pasa a ser una conversación sobre quién podría ser esa segunda. Una cifra pequeña abre lo que una grande cierra.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🎈</span><span class="ms-text"><strong>Dijiste «varias»:</strong> nadie te desmintió, la reunión siguió bien y saliste con la sensación de haberlo hecho mejor.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📉</span><span class="ms-text"><strong>Y la cuenta llegó después:</strong> a la tercera pregunta concreta no hubo nombres que dar. Quien lo notó no discutió contigo: dejó de contestar. Inflar no se cobra en la reunión, se cobra al abrir el producto.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

