const parteData={"hecho":{"nombre":"El hecho comprobable","icon":"🧾","estructura":{"title":"Qué es","info":"• Una afirmación que <strong>otro puede verificar sin creerte</strong><br>• Un archivo, una fecha, una foto, algo que se cuenta<br>• Lo que no se puede comprobar es opinión bien vestida"},"funcion":{"title":"Cómo se escribe","info":"• Se tachan los adjetivos y se mira qué queda en pie<br>• Lo que queda se acompaña de <strong>su fuente</strong><br>• Si no hay fuente, no entra en el relato"},"enfermedades":{"title":"Dónde se infla","info":"• Con «innovador», «líder» y «de altísima calidad»<br>• Al describir la prueba en vez de enseñarla<br>• Al afirmar sin comprobar: la ficha que decía diez páginas y tenía diecinueve"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Hechos que aguantan: <strong>abre sin internet</strong>, la ficha se imprime en carta, diecisiete misiones publicadas<br>• Y la regla que salió del error: <strong>el PDF es el único juez</strong>"}},"cifra":{"nombre":"La cifra con denominador","icon":"📊","estructura":{"title":"Qué es","info":"• Un número con <strong>de cuántos</strong> y <strong>en cuánto tiempo</strong><br>• «Veintidós de una sección de cuarenta y dos, en marzo»<br>• Sin eso, el número no significa nada"},"funcion":{"title":"Cómo se escribe","info":"• Se busca cada cifra y se le pregunta de cuántos y cuándo<br>• Se acepta que el número quede más pequeño<br>• Y se enseña <strong>el promedio</strong>, no el mejor día"},"enfermedades":{"title":"Dónde se infla","info":"• «Más de mil descargas», sin base ni plazo<br>• El pico presentado como si fuera lo normal<br>• El total acumulado desde siempre, contado como si fuera de este mes"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Las cifras que hoy se pueden enseñar son <strong>pequeñas y exactas</strong>: 17 misiones, 9 rutas, 14 fichas<br>• Una cifra chica y comprobable <strong>abre</strong> conversaciones que una grande y borrosa cierra"}},"falta":{"nombre":"Lo que todavía no es","icon":"🚧","estructura":{"title":"Qué es","info":"• El <strong>límite del proyecto dicho por uno mismo</strong><br>• Se dice antes de que la otra persona lo descubra<br>• No resta: es lo único que hace creíble el resto"},"funcion":{"title":"Cómo se escribe","info":"• Se escriben las tres cosas que <strong>más incomoda</strong> decir<br>• Se dicen con la misma calma que lo demás<br>• Y se acompañan de qué se está haciendo al respecto"},"enfermedades":{"title":"Dónde se infla","info":"• Al contar en presente lo que todavía no ocurrió<br>• Al esperar a que pregunten, y que la pregunta llegue en mal momento<br>• Al llamar «alianza» a lo que fue un patrocinio de una vez"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Lo que hay que decir sin que lo pregunten: la escuela es <strong>una y de prueba</strong>, las rutas declaran seis etapas y hay tres, y <strong>falta un maestro de fuera</strong> que revise el material"}},"fecha":{"nombre":"El relato caduca","icon":"📅","estructura":{"title":"Qué es","info":"• Todo relato lleva <strong>fecha y fecha de revisión</strong><br>• No porque cambie la verdad: porque cambia el proyecto<br>• Un texto quieto sobre algo que se mueve acaba siendo falso"},"funcion":{"title":"Cómo se escribe","info":"• Se lee entero <strong>como si fuera de otro</strong><br>• Se marca lo que ya no es cierto y se corrige con la fecha de hoy<br>• Se avisa a quien se lo creyó, si le afecta"},"enfermedades":{"title":"Dónde se infla","info":"• Con el «nadie se queja», que no significa que nadie se lo esté creyendo<br>• Con los textos de presentación, que nadie vuelve a abrir<br>• Con los símbolos: un candado que dice «no se comparte» sobre algo que sí se comparte"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Caso de la casa: el <strong>texto de presentación del repositorio</strong> sigue contando el proyecto anterior<br>• Y el <strong>candado 🔒</strong> de las tarjetas fue decorativo hasta que el repositorio se cerró de verdad"}}};
let labParte='hecho',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='📈 ¡'+name+' completó la Etapa 3 de la Ruta de la Marca (El relato: contar el proyecto sin inflarlo)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

